const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length === 0 || input[0] === '') return;

    const N = parseInt(input[0], 10);
    let idx = 1;

    const events = [];
    for (let i = 0; i < N; i++) {
        const type = input[idx++];
        const x = parseInt(input[idx++], 10);
        events.push({ type, x });
    }

    const friends = new Set();
    const lastReceived = {};
    const totalTime = {};
    const pending = {};

    let currentTime = 0;
    let firstEvent = true;

    for (let i = 0; i < events.length; i++) {
        const ev = events[i];

        if (ev.type === 'T') {
            currentTime += ev.x;
        } else {
            if (!firstEvent) {
                // If the previous record was not 'T', exactly 1 second has passed
                if (events[i - 1].type !== 'T') {
                    currentTime += 1;
                }
            } else {
                firstEvent = false;
            }

            const friend = ev.x;
            friends.add(friend);
            if (totalTime[friend] === undefined) {
                totalTime[friend] = 0;
                pending[friend] = false;
            }

            if (ev.type === 'R') {
                lastReceived[friend] = currentTime;
                pending[friend] = true;
            } else if (ev.type === 'E') {
                totalTime[friend] += (currentTime - lastReceived[friend]);
                pending[friend] = false;
            }
        }
    }

    const sortedFriends = Array.from(friends).sort((a, b) => a - b);
    for (const friend of sortedFriends) {
        if (pending[friend]) {
            console.log(`${friend} -1`);
        } else {
            console.log(`${friend} ${totalTime[friend]}`);
        }
    }
}

main();
